FlowRow(
    horizontalArrangement = Arrangement.spacedBy(8.dp),
    verticalArrangement = Arrangement.spacedBy(8.dp),
) {
    val icon: @Composable (MonarchSlaIndicatorState) -> Unit = { state ->
        MonarchIcon(
            when (state) {
                MonarchSlaIndicatorState.OnTrack, MonarchSlaIndicatorState.AtRisk -> SampleIcons.Clock
                MonarchSlaIndicatorState.Breached -> SampleIcons.Error
                MonarchSlaIndicatorState.Paused -> SampleIcons.PauseCircle
                MonarchSlaIndicatorState.Met -> SampleIcons.Success
                MonarchSlaIndicatorState.NotApplicable -> SampleIcons.Dash
            },
            contentDescription = null,
        )
    }
    MonarchSlaIndicator(MonarchSlaIndicatorState.{{indicators.0.state|pascal}}, dueAt = {{now|millis}} + {{indicators.0.dueInMinutes}} * 60_000L, now = {{now|millis}}, icon = icon)
    MonarchSlaIndicator(MonarchSlaIndicatorState.{{indicators.1.state|pascal}}, dueAt = {{now|millis}} + {{indicators.1.dueInMinutes}} * 60_000L, now = {{now|millis}}, icon = icon)
    MonarchSlaIndicator(MonarchSlaIndicatorState.{{indicators.2.state|pascal}}, dueAt = {{now|millis}} + {{indicators.2.dueInMinutes}} * 60_000L, now = {{now|millis}}, icon = icon)
    MonarchSlaIndicator(MonarchSlaIndicatorState.{{indicators.3.state|pascal}}, icon = icon)
    MonarchSlaIndicator(MonarchSlaIndicatorState.{{indicators.4.state|pascal}}, icon = icon)
    MonarchSlaIndicator(MonarchSlaIndicatorState.NotApplicable, showNotApplicable = {{indicators.5.showNone}}, icon = icon)
}

