FlowRow(
    horizontalArrangement = Arrangement.spacedBy(8.dp),
    verticalArrangement = Arrangement.spacedBy(8.dp),
) {
    val icon: @Composable (MonarchSlaIndicatorState) -> Unit = { state ->
        MonarchIcon(
            when (state) {
                MonarchSlaIndicatorState.OnTrack, MonarchSlaIndicatorState.AtRisk -> SampleIcons.Clock
                MonarchSlaIndicatorState.Breached -> SampleIcons.Error
                MonarchSlaIndicatorState.Paused -> SampleIcons.PauseCircle
                MonarchSlaIndicatorState.Met -> SampleIcons.Success
                MonarchSlaIndicatorState.NotApplicable -> SampleIcons.Dash
            },
            contentDescription = null,
        )
    }
    MonarchSlaIndicator(MonarchSlaIndicatorState.OnTrack, dueAt = 1_768_212_000_000L + 135 * 60_000L, now = 1_768_212_000_000L, icon = icon)
    MonarchSlaIndicator(MonarchSlaIndicatorState.AtRisk, dueAt = 1_768_212_000_000L + 20 * 60_000L, now = 1_768_212_000_000L, icon = icon)
    MonarchSlaIndicator(MonarchSlaIndicatorState.Breached, dueAt = 1_768_212_000_000L + -40 * 60_000L, now = 1_768_212_000_000L, icon = icon)
    MonarchSlaIndicator(MonarchSlaIndicatorState.Paused, icon = icon)
    MonarchSlaIndicator(MonarchSlaIndicatorState.Met, icon = icon)
    MonarchSlaIndicator(MonarchSlaIndicatorState.NotApplicable, showNotApplicable = true, icon = icon)
}

Column {
    Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
        MonarchText(text = "First response")
        MonarchSlaIndicator(MonarchSlaIndicatorState.Met, variant = MonarchSlaIndicatorVariant.Text)
    }
    Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
        MonarchText(text = "Next response")
        MonarchSlaIndicator(
            MonarchSlaIndicatorState.AtRisk,
            variant = MonarchSlaIndicatorVariant.Text,
            dueAt = nextDue,
        )
    }
    Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
        MonarchText(text = "Resolution")
        MonarchSlaIndicator(
            MonarchSlaIndicatorState.NotApplicable,
            variant = MonarchSlaIndicatorVariant.Text,
            showNotApplicable = true,
        )
    }
}
